/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
'use strict';
const D=globalThis.RA.D;
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+q.s,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('plover','From Old French plover/pluvier and Latin pluvia, “rain”; the deeper history is not certain.',C('plover.s1','ornithology','A ringed plover ran along the tideline, stopping to probe the wet sand.','环颈鸻沿着潮线奔跑，停下来啄探湿沙。','ran along the tideline','past simple','The bird name is used literally for a shorebird.'),M('We watched a plover building its nest high in an oak tree.','We watched a plover probing the shore.','A plover is a shorebird; the sentence confused it with a diving seabird.','meaning'),[Q(1,'Which habitat best fits a plover in this sentence: “The plover searched the beach”?','a shore','a desert','a treetop','Plover names a shorebird often seen on open shores.'),Q(1,'Choose the natural verb: “The plover ___ across the wet sand.”','ran','boiled','voted','The context uses plover as a bird moving along a beach.'),Q(1,'What kind of animal is a plover?','a shorebird','a freshwater fish','a flowering shrub','The source sense identifies a bird.'),Q(1,'Which detail is most plausible about a plover?','It probes sand for small food.','It builds dams underwater.','It grows fruit in a pod.','Shorebirds commonly probe shore sand for food.')]);
P('plow','Old English plōh; its further Germanic origin is uncertain.',C('plow.s1','agriculture','The farmer used a plow to turn the soil before planting barley.','农夫在种大麦前用犁翻土。','used a plow to turn the soil','simple past','The implement sense is distinguished from plow as a verb.'),M('The plow harvested the ripe barley from the field.','The plow turned the soil before planting.','A plow prepares soil; a combine harvests grain.','meaning'),[Q(1,'What did the farmer use the plow for?','turning soil','measuring rainfall','cutting wool','A plow is an agricultural implement that turns soil.'),Q(1,'Which object can be called a plow?','a soil-turning implement','a grain-storage silo','a seed packet','The noun sense names the implement, not the crop or container.'),Q(1,'Choose the best completion: “Before sowing, they pulled the ___ through the field.”','plow','memo','podcast','The plow breaks and turns soil before sowing.'),Q(1,'What is the plow’s role in the sentence?','It prepares the field.','It waters the barley.','It tests the seeds.','Turning the soil is field preparation.')]);
P('ploy','Recorded in 18th-century Scottish and northern English dialect for a frolic; possibly shortened from employ, though the proposal is uncertain.',C('ploy.s1','strategy','Calling the delay a “technical pause” was a ploy to avoid answering the question.','把延迟称作“技术暂停”是为了回避回答问题的策略。','a ploy to avoid answering','infinitive purpose','Here ploy means a tactic intended to achieve an advantage.'),M('Her ploy was to tell the truth clearly so nobody would be misled.','Her ploy was to distract the panel from the missing figures.','A ploy is a tactic, often a deceptive one, not straightforward honesty.','meaning'),[Q(1,'Why was the “technical pause” called a ploy?','It helped avoid the question.','It repaired the equipment.','It recorded the answer.','A ploy is a tactic used to gain an advantage or evade something.'),Q(1,'Which is closest in meaning to ploy here?','tactic','accident','apology','The sentence describes a deliberate tactic.'),Q(1,'What intention does the ploy serve?','to distract the panel','to publish the report','to welcome a guest','The example explicitly says it avoids an answer.'),Q(1,'Which action is most likely a ploy?','Changing the subject to escape a difficult question.','Answering the question directly.','Asking for the question to be repeated.','A ploy is a maneuver for a desired effect.')]);
P('pluck','Old English pluccian “to pull off,” from a West Germanic source.',C('pluck.s2','gardening','She plucked a ripe apple from the low branch.','她从低矮的树枝上摘下一颗熟苹果。','plucked an apple from the branch','simple past','The verb sense is pulling fruit from a plant.'),M('He plucked the apple by leaving it attached to the tree.','He plucked the apple from the branch.','Pluck means remove by pulling; leaving it attached contradicts the verb.','meaning'),[Q(2,'What did she do to the apple?','pulled it off the branch','buried it under the tree','painted it on the branch','Pluck means to pull something off or out.'),Q(2,'Which sentence uses pluck in its fruit sense?','He plucked a pear from the tree.','He watered the pear tree.','He counted the pears in a basket.','The fruit sense means picking by pulling.'),Q(2,'What did the branch provide?','the place from which the apple was pulled','a tool for cutting the apple','a container for storing the apple','The apple was plucked from the branch.'),Q(2,'Choose the closest replacement: “She plucked a flower.”','She picked a flower by pulling it.','She planted a flower.','She watered a flower.','In this sense, pluck means pick by pulling.')]);
P('plug','Probably from a Low Germanic word for a peg or stopper; the precise origin is uncertain.',C('plug.s2','household','He pushed a cork plug into the bottle to keep the juice fresh.','他把软木塞塞进瓶子，以保持果汁新鲜。','pushed a cork plug into the bottle','past + object','The stopper sense is used; “plug” also has electrical and blocking senses.'),M('She used a plug to pour juice out of the bottle.','She used a plug to seal the bottle.','A stopper closes an opening; it does not pour liquid out.','meaning'),[Q(2,'What does the plug do in the bottle?','seals the opening','heats the juice','measures the juice','This plug is a stopper that closes the bottle.'),Q(2,'Which object is a plug in this sense?','a cork stopper','a glass of juice','a bottle label','The source sense includes a stopper.'),Q(2,'Choose the best verb: “He ___ the opening with a plug.”','sealed','squeezed','weighed','A stopper plug seals an opening.'),Q(2,'Why was a plug useful here?','It kept the juice from spilling.','It made the juice colder.','It changed the juice’s flavor.','The plug closes the bottle and helps preserve its contents.')]);
P('plum','Old English plume, borrowed through Latin prunum from Greek proumnon, “plum.”',C('plum.s1','food','A ripe plum split open, revealing its sweet red flesh and hard stone.','熟李子裂开，露出甜美的红色果肉和坚硬的果核。','a ripe plum split open','simple past','This is the fruit sense, not the figurative “plum job.”'),M('She removed the plum’s soft edible flesh and ate the stone.','She ate the soft flesh and discarded the plum stone.','The stone is the hard seed inside a plum, not its edible flesh.','meaning'),[Q(1,'What is the hard stone inside a plum?','its seed','its skin','its stem','A plum is a stone fruit with a hard seed.'),Q(1,'Which item is a plum?','a sweet fruit with a stone','a leafy herb','a grain stalk','The sense identifies a fruit.'),Q(1,'What did the plum reveal when it split?','red flesh and a hard stone','a flower and pollen','a pod of peas','The example describes the fruit’s flesh and seed.'),Q(1,'Which food could have a plum stone?','a ripe plum','a slice of bread','a bowl of soup','Plums are stone fruits.')]);
P('plumage','From French plumage, based on plume “feather,” ultimately Latin pluma.',C('plumage.s1','ornithology','The peacock’s blue-green plumage shimmered in the afternoon sun.','孔雀蓝绿色的羽毛在午后阳光下闪闪发亮。','peacock’s blue-green plumage','possessive noun phrase','Plumage is a bird’s feathers considered together.'),M('The bird shed its plumage of scales each spring.','The bird’s plumage consisted of feathers.','Plumage means feathers; scales are a different covering.','meaning'),[Q(1,'What shimmered in the sun?','the peacock’s feathers','its beak','its nest','Plumage means a bird’s feathers as a whole.'),Q(1,'Which animal feature is plumage?','feathers','scales','whiskers','The word refers to feathers.'),Q(1,'A bird with bright plumage has what?','colorful feathers','a loud call','a long migration route','Plumage describes the bird’s feather covering.'),Q(1,'Which phrase uses plumage correctly?','the eagle’s dark plumage','the fish’s plumage of scales','the tree’s plumage of bark','Birds have plumage; this example applies it to an eagle.')]);
P('plumb','From Latin plumbum “lead”; a lead weight on a line was used to test verticality.',C('plumb.s2','construction','The mason checked the wall with a plumb before adding the next course of bricks.','砌砖前，泥瓦匠用铅锤检查墙面是否垂直。','with a plumb','instrument phrase','The noun is a lead weight used to establish a vertical line.'),M('The mason used a plumb to see whether the wall was level from side to side.','The mason used a plumb to check whether the wall was vertical.','A plumb line checks vertical alignment; a level checks horizontal alignment.','meaning'),[Q(2,'What does the mason check with a plumb?','vertical alignment','the wall’s color','the brick count','A plumb weight indicates a true vertical line.'),Q(2,'What is a plumb in this sentence?','a lead weight used for alignment','a brick-cutting saw','a measuring cup','The noun sense is a plumb bob or weight.'),Q(2,'Why check before adding bricks?','to keep the wall vertical','to dry the mortar','to select a paint color','The plumb reveals whether the wall leans.'),Q(2,'Which tool is closest to a plumb?','a weighted line','a thermometer','a compass for north','A plumb uses a weight and line to show vertical.')]);
P('plumber','Formed from plumb, reflecting the traditional use of lead pipes; a plumber installs and repairs water systems.',C('plumber.s1','trades','The plumber replaced the leaking pipe beneath the kitchen sink.','水管工更换了厨房水槽下方漏水的管子。','replaced the leaking pipe','simple past','A plumber is a tradesperson who works on water and drainage pipes.'),M('The plumber repaired the patient’s broken arm.','The plumber repaired the leaking water pipe.','A plumber works on pipes and plumbing systems, not medical injuries.','meaning'),[Q(1,'What job did the plumber do?','replaced a leaking pipe','treated a broken arm','rewired a radio','Plumbers install and repair pipe systems.'),Q(1,'Who would you call for a leaking sink pipe?','a plumber','a poet','a pollinator','A plumber handles water pipes and fittings.'),Q(1,'Which task best suits a plumber?','repairing a drain','writing a sonnet','testing pollen','The occupation centers on plumbing systems.'),Q(1,'What was leaking in the example?','a pipe','a roof tile','a fuel tank','The plumber replaced the pipe beneath the sink.')]);
P('plumbing','From plumber and plumb, ultimately Latin plumbum “lead,” once widely used for pipes.',C('plumbing.s1','building','The old house’s plumbing carried water from the mains to every bathroom.','老房子的管道系统把自来水输送到每间浴室。','house’s plumbing carried water','possessive subject','Here plumbing means the network of pipes and fittings.'),M('The house’s plumbing carried water through its electrical wires.','The house’s plumbing carried water through its pipes.','Plumbing carries water in pipes; electrical wires carry current.','meaning'),[Q(1,'What did the plumbing carry?','water','electric current','fresh air','The system in the example is a water-pipe network.'),Q(1,'Which system is plumbing?','pipes and fittings for water','the building’s wiring','its heating timetable','Plumbing refers to water and drainage pipework.'),Q(1,'Where did the water go?','to every bathroom','to the roof antenna','to the garden fence','The plumbing connected the mains with the bathrooms.'),Q(1,'What might an inspection of plumbing reveal?','a leaking pipe','a spelling error','a bird’s feathers','Plumbing consists of pipes and related fittings.')]);
P('plume','From Old French plume and Latin pluma “feather”; the smoke sense extends the idea of a rising feather-like column.',C('plume.s2','weather','A dark plume of smoke rose above the factory after the fire.','火灾后，一股黑烟从工厂上空升起。','plume of smoke rose','noun phrase + verb','The figurative plume is a visible column of smoke.'),M('A plume of smoke sank into a solid block on the ground.','A plume of smoke rose above the factory.','A plume is a rising column or cloud, not a solid block.','meaning'),[Q(2,'What rose above the factory?','a column of smoke','a feathered wing','a stone wall','Plume can describe a rising column of smoke.'),Q(2,'Which image fits plume in this context?','smoke spreading upward','water flowing underground','soil turning over','The example uses the extended column sense.'),Q(2,'What caused the smoke plume?','a fire','a harvest','a rainfall measurement','The sentence says it rose after the fire.'),Q(2,'Choose the best meaning: “a plume of smoke”','a rising cloud or column of smoke','a bird’s nest','a smoke detector','The word describes the smoke’s visible shape.')]);
P('plummet','From French plombet, “small lead weight,” related to plomb; the verb later developed the sense of dropping steeply.',C('plummet.s1','finance','After the safety warning, the company’s share price plummeted by a third.','安全警告发布后，公司的股价暴跌了三分之一。','price plummeted by a third','intransitive verb','Plummet describes a sudden, steep fall.'),M('After the warning, the share price plummeted slowly by one cent over ten years.','After the warning, the share price plummeted by a third in a day.','Plummet implies a sudden, steep drop, not a tiny gradual change.','meaning'),[Q(1,'What happened to the share price?','It fell sharply.','It stayed exactly level.','It rose gently.','Plummet means to drop suddenly and steeply.'),Q(1,'Which verb is closest to plummeted?','tumbled','stabilized','increased','The price underwent a steep fall.'),Q(1,'Why did the price plummet in the example?','a safety warning was issued','the firm opened a new office','the company paid a dividend','The sentence links the sharp fall to the warning.'),Q(1,'What does “by a third” measure?','the size of the fall','the number of shares traded','the warning’s length','The price declined by one-third of its value.')]);
P('plump','The adjective is recorded from late Middle English and likely comes through Dutch/Germanic forms meaning thick or blunt; exact development is uncertain.',C('plump.s1','description','The plump robin stood beside the feeder, its feathers puffed against the cold.','圆滚滚的知更鸟站在喂食器旁，羽毛因寒冷而蓬起。','plump robin','adjective before noun','Plump describes a rounded, pleasantly full shape.'),M('The plump balloon was completely flat and empty.','The plump cushion was rounded and full.','Plump describes a rounded or full shape, not something flat.','meaning'),[Q(1,'How is the robin described?','rounded and full','thin and angular','wet and muddy','Plump means pleasantly full or rounded.'),Q(1,'Which object could be plump?','a full cushion','a razor-thin sheet','an empty cup','The adjective describes a rounded, full shape.'),Q(1,'What made the robin’s feathers puff?','the cold','a plow','a thunderstorm inside the feeder','The context states that its feathers puffed against the cold.'),Q(1,'Choose a close synonym for plump here.','round','hollow','pointed','Plump suggests a rounded full appearance.')]);
P('plunder','From Dutch plunderen “to rob or pillage”; deeper origin is uncertain.',C('plunder.s1','history','The invading army plundered the village and carried off grain and tools.','入侵军队洗劫了村庄，掠走粮食和工具。','plundered the village','simple past','The verb means to steal goods by force, especially in war.'),M('The army plundered the village by returning every stolen tool to its owner.','The army plundered the village and seized its supplies.','Plunder means to rob or pillage, not to return property.','meaning'),[Q(1,'What did the army do?','robbed the village','rebuilt the village','surveyed the village','Plunder means to steal goods, often during conflict.'),Q(1,'Which detail signals plunder?','carrying off grain and tools','planting new crops','repairing a bridge','Seizing goods is characteristic of plundering.'),Q(1,'Which verb is closest to plundered?','pillaged','donated','measured','The army took goods by force.'),Q(1,'What happened to the village supplies?','They were seized.','They were polished.','They were planted.','The sentence says the army carried them off.')]);
P('plunge','From Old French plongier, from Latin plumbicare “to plunge like lead”; ultimate history is linked to plumbum “lead.”',C('plunge.s1','movement','She plunged into the lake before the others had finished counting down.','别人还没倒数完，她就跳进了湖里。','plunged into the lake','verb + into','The verb describes a sudden jump or dive into something.'),M('She plunged into the lake by remaining safely on the dry shore.','She plunged into the lake with a sudden dive.','Plunge into means enter or jump into suddenly; staying ashore contradicts it.','meaning'),[Q(1,'What did she do?','jumped suddenly into the lake','walked away from the lake','waited beside the lake','Plunge into describes a sudden entry.'),Q(1,'Which phrase best paraphrases plunged into?','dived into','looked at','dried beside','The example describes a quick dive.'),Q(1,'What happened before the others finished counting?','She entered the water.','The lake froze.','The others left.','She plunged in before the countdown ended.'),Q(1,'Which movement is a plunge?','a sudden dive into water','a slow walk along a path','a careful turn of a page','Plunge implies abrupt entry or movement downward.')]);
P('plural','From Latin pluralis “of more,” based on plus; the grammatical use refers to more than one.',C('plural.s1','grammar','In English, “books” is plural because it names more than one book.','英语中，books 是复数，因为它指不止一本书。','books is plural','predicate adjective','Plural describes a form referring to more than one.'),M('“Books” is plural because it refers to exactly one book.','“Books” is plural because it refers to more than one book.','Plural normally marks more than one; the correction fixes the number explanation.','grammar'),[Q(1,'Why is “books” plural?','It refers to more than one book.','It refers to a book’s cover.','It names a kind of paper.','Plural forms normally refer to more than one.'),Q(1,'Which form is plural?','children','child','childhood','Children names more than one child.'),Q(1,'What does plural contrast with?','singular','past tense','comparative','Singular refers to one; plural to more than one.'),Q(1,'In “two cars,” which word is plural?','cars','two','in','Cars is the plural noun form.')]);
P('plural form','Transparent phrase: plural + form; plural derives from Latin pluralis, “of more than one.”',C('plural form.s1','grammar','“Mice” is the plural form of “mouse.”','mice 是 mouse 的复数形式。','plural form of mouse','noun phrase','The phrase names the word form used for multiple referents.'),M('“Mice” is the plural form of “mouse” when there is only one mouse.','“Mice” is the plural form of “mouse” when there is more than one.','The plural form indicates multiple mice, not a single one.','grammar'),[Q(1,'What is the plural form of mouse?','mice','mouses only','mouse’s','Mice is the irregular plural form.'),Q(1,'When is a plural form used?','for more than one','for a past event','for a person’s name','Plural marks more than one.'),Q(1,'Which pair shows singular then plural?','foot / feet','feet / foot','fast / faster','Foot is singular and feet plural.'),Q(1,'What does “plural form” name?','a word form for multiple items','a verb’s future tense','a shortened word','The phrase refers to a form expressing plurality.')]);
P('pluralism','Plural + -ism; the suffix forms a noun for a system or doctrine, while plural ultimately comes from Latin plus “more.”',C('pluralism.s1','society','The city’s pluralism was reflected in its many languages, faiths, and traditions.','这座城市的多元性体现在多种语言、信仰和传统中。','city’s pluralism','possessive subject','This sense is the coexistence of different groups or viewpoints.'),M('The city’s pluralism meant that every resident followed one identical tradition.','The city’s pluralism allowed different traditions to coexist.','Pluralism implies variety or coexistence, not enforced uniformity.','meaning'),[Q(1,'What did the city’s pluralism include?','different languages and traditions','one required language only','a single uniform custom','Pluralism involves the coexistence of diverse groups or beliefs.'),Q(1,'Which setting best illustrates pluralism?','a community where several faiths coexist','a town that bans every other language','a school with one student','Diverse beliefs existing together illustrate pluralism.'),Q(1,'What does the suffix -ism help form in pluralism?','a noun for a system or condition','a past-tense verb','a diminutive adjective','Pluralism names a condition or doctrine.'),Q(1,'Which idea is opposed to pluralism here?','forced uniformity','cultural variety','coexistence','Pluralism emphasizes multiple traditions living together.')]);
P('plurality','Plural + -ity; the election sense developed for the largest number of votes without an absolute majority.',C('plurality.s1','elections','Nora won a plurality of the votes, though more voters chose other candidates combined.','虽然其他候选人获得的票数合计更多，诺拉仍以相对多数票获胜。','a plurality of the votes','of-phrase','A plurality is the largest share, even if it is less than half.'),M('Nora won a plurality even though another candidate received more votes than she did.','Nora won a plurality by receiving more votes than any single rival.','A plurality is more votes than each rival individually, not fewer than one rival.','meaning'),[Q(1,'Did Nora necessarily receive over half of all votes?','No; a plurality can be less than half.','Yes, by definition.','Only if there were two candidates.','Plurality means the largest number, not necessarily a majority.'),Q(1,'What made Nora the plurality winner?','She outpolled each individual rival.','She received no votes.','Every voter chose all candidates.','A plurality is more votes than any one competitor.'),Q(1,'Which statement defines a plurality?','the largest vote total, even below half','exactly half of the votes','a tie among all candidates','Plurality does not require a majority.'),Q(1,'If A gets 40%, B 35%, and C 25%, who has a plurality?','A','B','C','A has the largest share although it is below 50%.')]);
P('plus','From Latin plus “more”; its mathematical and general senses retain the idea of addition or advantage.',C('plus.s2','evaluation','The extra hour of daylight was a plus for the outdoor concert.','多出来的一小时日照对户外音乐会来说是个优点。','was a plus for','noun complement','As a noun, plus means an advantage or favorable feature.'),M('The extra daylight was a plus because it made the concert worse.','The extra daylight was a plus because it improved the concert.','A plus is an advantage, so the reason should be favorable.','meaning'),[Q(2,'What was a plus for the concert?','the extra daylight','the broken sound system','the cancelled performance','As a noun, plus means a beneficial feature.'),Q(2,'Which phrase uses plus as a noun?','One plus is the quiet location.','Add three plus four.','The temperature is plus five.','“One plus” names an advantage.'),Q(2,'Why was the extra hour helpful?','It provided more daylight.','It shortened the concert.','It removed the audience.','The stated advantage was longer daylight.'),Q(2,'Choose the closest meaning: “That is a real plus.”','That is a real advantage.','That is a subtraction.','That is a mistake.','The noun plus means a favorable point.')]);
P('plush','From French peluche, probably via earlier Germanic forms for shaggy or woolly fabric; the luxury sense developed later.',C('plush.s1','textiles','The hotel’s plush armchairs were upholstered in deep velvet.','酒店里豪华舒适的扶手椅包着厚实的天鹅绒。','plush armchairs','adjective before noun','Plush describes luxurious comfort or a thick soft material.'),M('The plush chair was hard, bare, and uncomfortable.','The plush chair was thickly padded and comfortable.','Plush implies luxurious comfort or soft, thick fabric.','meaning'),[Q(1,'What made the armchairs plush?','their luxurious soft upholstery','their broken legs','their narrow metal seats','Plush describes comfortable luxury or soft material.'),Q(1,'Which chair sounds plush?','a velvet, deeply padded armchair','a bare wooden stool','a cracked plastic crate','A plush chair is soft and comfortable.'),Q(1,'In the example, what does plush describe?','the armchairs','the hotel address','the velvet color alone','The adjective modifies the armchairs.'),Q(1,'Choose the nearest meaning of plush here.','luxuriously comfortable','unfinished','temporary','The context uses the comfort sense of plush.')]);
P('Pluto','Named in 1930 from Pluto, the Roman god of the underworld; the name was proposed for the newly found distant planet.',C('Pluto.s1','astronomy','Pluto travels around the Sun beyond Neptune in a cold, distant orbit.','冥王星在海王星之外沿寒冷而遥远的轨道绕太阳运行。','Pluto travels around the Sun','proper noun subject','The astronomical sense is the dwarf planet; the source also records the mythological name.'),M('Pluto is a moon orbiting inside Earth’s atmosphere.','Pluto is a dwarf planet orbiting the Sun beyond Neptune.','Pluto is a distant dwarf planet, not an atmospheric moon.','meaning'),[Q(1,'Where does Pluto orbit?','the Sun','Earth’s atmosphere','the Moon','The astronomical sense identifies Pluto as a solar-system body.'),Q(1,'Which description fits Pluto?','a dwarf planet beyond Neptune','a star inside the Sun','a satellite of Earth','Pluto is classified as a dwarf planet.'),Q(1,'What is the origin of Pluto’s astronomical name?','the Roman underworld god','a Greek sea nymph','an ancient city in China','The planet’s name was taken from the Roman god.'),Q(1,'Which statement matches the example?','Pluto has a distant orbit around the Sun.','Pluto is a cloud below Earth.','Pluto circles Neptune as its moon.','The source sense describes a dwarf planet beyond Neptune.')]);
P('plutonium','Named from Pluto plus the chemical suffix -ium, following uranium and neptunium; the element was identified in 1940.',C('plutonium.s1','chemistry','The reactor used plutonium as fuel, with strict controls for handling the radioactive metal.','反应堆使用钚作燃料，并严格管控这种放射性金属的处理。','used plutonium as fuel','noun as object','Plutonium is a radioactive metallic element used in some nuclear fuels.'),M('The lab stored plutonium beside food because it is harmless and nonradioactive.','The lab stored plutonium under strict controls because it is radioactive.','Plutonium is radioactive and requires controlled handling.','meaning'),[Q(1,'What kind of material is plutonium?','a radioactive metal','a harmless sugar','a plant fiber','The source sense defines it as a radioactive metal.'),Q(1,'What was plutonium used for in the example?','reactor fuel','wall insulation','a cooking spice','The context states its use as fuel.'),Q(1,'Why were handling controls strict?','because plutonium is radioactive','because it melts in sunlight','because it attracts insects','The metal is radioactive.'),Q(1,'Which field studies plutonium as an element?','chemistry','botany','musicology','Plutonium is a chemical element.')]);
P('ply','From Old English pli, from Latin plicare “to fold”; verb senses include working busily and regularly serving a route.',[C('ply.s1','materials','The jacket’s two-ply wool stayed warm without feeling bulky.','这件夹克的双股羊毛保暖却不显臃肿。','two-ply wool','compound modifier','The noun sense names a layer or strand in material.'),C('ply.s2','transport','Ferries ply the route between the island and the mainland every hour.','渡轮每小时往返岛屿与大陆之间的航线。','ply the route','plural subject + verb','The verb sense means to travel a route regularly.')],M('Ferries ply the route once a century.','Ferries ply the route every hour.','To ply a route is to serve or travel it regularly.','collocation'),[Q(1,'What does two-ply describe?','two strands or layers','two ferry routes','two jacket pockets','Ply as a noun means a layer or strand.'),Q(2,'What do the ferries do?','travel the route regularly','close the island harbor','build a new mainland','To ply a route is to serve it on a regular basis.'),Q(1,'Which product could be described as three-ply?','a layered tissue','a one-piece stone','a single ferry','Ply counts layers or strands.'),Q(2,'Which sentence uses ply as a verb?','Buses ply the road all day.','The cloth has four plies.','The road is narrow.','The first sentence uses ply for regularly serving a route.')]);
P('plywood','A modern compound of ply, “layer,” and wood; it names board made by bonding layers of veneer.',C('plywood.s1','materials','The carpenter cut a sheet of plywood for the cabinet’s back panel.','木匠裁下一块胶合板，作为柜子的背板。','sheet of plywood','noun complement','Plywood is manufactured sheet material made from bonded wood veneers.'),M('The cabinet back was made from one solid piece of transparent glass plywood.','The cabinet back was made from bonded layers of wood veneer.','Plywood is a wood product built from bonded veneer layers.','meaning'),[Q(1,'What did the carpenter cut?','a sheet of bonded wood layers','a metal pipe','a glass bottle','Plywood is sheet material made from veneers.'),Q(1,'Why was plywood used?','for a cabinet back panel','to grow a tree','to insulate a wire','The example uses plywood as a board material.'),Q(1,'How is plywood constructed?','wood veneers are bonded in layers','solid logs are woven together','paper is melted into metal','Plywood consists of bonded veneer layers.'),Q(1,'Which project might use plywood?','building a cabinet panel','polishing a pearl','writing a poem','Plywood is a common sheet material for panels.')]);
P('pneumatic','From Greek pneumatikos “of air or breath,” based on pneuma “air, breath.”',C('pneumatic.s1','engineering','A pneumatic drill uses compressed air to drive its hammering mechanism.','气动钻利用压缩空气驱动锤击机构。','pneumatic drill','adjective before noun','The adjective means operated by compressed air.'),M('The pneumatic drill was powered only by sunlight, with no air supply.','The pneumatic drill was powered by compressed air.','Pneumatic equipment operates by compressed air; sunlight alone does not power its air hammer.','meaning'),[Q(1,'What powers the drill?','compressed air','a hand-cranked spring','flowing ink','Pneumatic machinery works by air pressure.'),Q(1,'Which device is pneumatic?','an air-powered hammer','a solar-powered clock','a water-filled vase','The source sense describes equipment operated by compressed air.'),Q(1,'What does pneumatic modify in the example?','drill','air','mechanism','Pneumatic is the adjective describing the drill.'),Q(1,'Which phrase paraphrases pneumatic drill?','air-powered drill','electric-only drill','wooden hand tool','Compressed air drives the drill.')]);
P('pneumonia','From Greek pneumōn “lung,” through medical Latin and New Latin; the name refers to a serious lung disease.',C('pneumonia.s1','medicine','The physician diagnosed pneumonia after the scan showed infection in both lungs.','扫描显示双肺感染后，医生诊断为肺炎。','diagnosed pneumonia','medical verb + object','Pneumonia is an illness affecting the lungs; diagnosis belongs to a clinician.'),M('The scan showed a broken wrist, so the physician diagnosed pneumonia.','The scan showed lung infection, so the physician diagnosed pneumonia.','Pneumonia is a lung illness; a wrist fracture does not support that diagnosis.','meaning'),[Q(1,'Which organ is affected by pneumonia?','the lungs','the kidneys','the ankle','Pneumonia is a lung disease.'),Q(1,'What supported the diagnosis in the example?','infection in both lungs','a broken wrist','a damaged tooth','The scan showed infection in the lungs.'),Q(1,'Who made the diagnosis?','a physician','a plumber','a pollster','A physician is a medical professional.'),Q(1,'Which symptom report would fit a lung illness better?','difficulty breathing with a lung infection','a sprained finger only','a chipped fingernail','Pneumonia affects lung function.')]);
P('poach','From Old French pochier “to put into a pocket”; the cooking sense may refer to food enclosed in liquid, while the illegal-hunting sense developed separately.',[C('poach.s1','cooking','Poach the eggs gently in barely simmering water for four minutes.','把鸡蛋放在微沸的水中轻轻水煮四分钟。','poach the eggs','imperative + object','The cooking sense means simmering food gently in liquid.'),C('poach.s2','law and employment','The rival firm tried to poach two engineers by offering them higher salaries.','竞争公司试图以更高薪水挖走两名工程师。','poach engineers','verb + object','The figurative sense is to take people unfairly from another group.')],M('The company poached the engineers by asking them to stay with their current employer.','The company poached the engineers by enticing them away from their current employer.','Poach staff means unfairly recruit them away from another employer.','collocation'),[Q(1,'How should the eggs be cooked?','gently in barely simmering water','deep-fried in hot oil','baked in dry flour','Poaching cooks food gently in liquid.'),Q(2,'What did the rival firm try to do?','recruit the engineers away','train the engineers’ children','report the engineers to police','To poach employees is to entice them from another employer.'),Q(1,'Which dish could contain a poached egg?','an egg cooked gently in water','an egg frozen in ice','an egg roasted in its shell','Poach is a gentle liquid-cooking method.'),Q(2,'Why is “poach two engineers” figurative?','the firm wants to take workers from a rival','the firm wants to cook engineers','the firm wants to hire no one','The verb extends from taking something improperly to recruiting staff.')]);
P('pocket','From Anglo-Norman/French poquet, a diminutive of poke “bag”; the small garment pouch sense came first.',[C('pocket.s1','clothing','I found the train ticket in the inside pocket of my coat.','我在外套的内口袋里找到了火车票。','in the inside pocket','prepositional phrase','The sewn pouch in clothing is the basic noun sense.'),C('pocket.s2','finance','The repair will cost less if we pay from our own pockets.','如果我们自己掏钱维修，费用会低一些。','from our own pockets','fixed possessive phrase','Pocket can refer to money available to a person.')],M('She put the ticket into the coat’s pocket by sewing it onto the outside sleeve.','She put the ticket into the coat’s pocket, a small pouch sewn into it.','A clothing pocket is a pouch, not simply any item attached to a sleeve.','meaning'),[Q(1,'Where was the train ticket?','inside a sewn pouch in the coat','inside the train engine','under the platform','A pocket in clothing is a small pouch.'),Q(2,'What does “from our own pockets” mean?','using our own money','using borrowed tools','using public transport','Pocket can refer to money one has available.'),Q(1,'Which item is a pocket?','a pouch sewn into trousers','a button on a shirt','a belt around a coat','The source sense is a small sewn pouch.'),Q(2,'If a repair comes out of your pocket, who pays?','you do','the repair pays','nobody ever pays','The phrase means paying with one’s own money.')]);
P('pocket money','A transparent compound of pocket + money, attested in the 19th century for a small personal allowance.',C('pocket money.s1','family','Her parents gave her pocket money each Saturday so she could buy a snack or save it.','父母每周六给她零花钱，让她买零食或存起来。','gave her pocket money','indirect object','Pocket money is a small amount for personal spending.'),M('He used his pocket money to buy a factory for the family.','He used his pocket money to buy a small snack.','Pocket money is a modest allowance, not a sum suited to buying a factory.','meaning'),[Q(1,'What was the money for?','small personal purchases or saving','paying the national budget','buying a whole factory','Pocket money is a small personal allowance.'),Q(1,'When did she receive pocket money?','each Saturday','once every hundred years','only at the checkout','The sentence says her parents gave it weekly.'),Q(1,'Which child has pocket money?','one given a small allowance','one who owns a bank','one paid a national salary','The term means a small spending allowance.'),Q(1,'What could she do with the allowance?','buy a snack or save it','repair the moon','hire the parents','The example states those modest uses.')]);
P('pocketbook','From pocket + book, originally a small book-like case or wallet; it can also mean a person’s spending power.',C('pocketbook.s1','finance','The higher bus fare will hurt the pocketbook of commuters on tight budgets.','对预算紧张的通勤者来说，公交票价上涨会加重经济负担。','hurt the pocketbook','idiom-like object phrase','Here pocketbook refers figuratively to available personal money.'),M('The fare increase will hurt commuters’ pocketbooks by making their trips cheaper.','The fare increase will hurt commuters’ pocketbooks by raising their costs.','A higher fare strains a budget; it does not make travel cheaper.','meaning'),[Q(1,'What does pocketbook mean in the example?','a person’s available money','a route map','a bus seat','The figurative sense means spending power or budget.'),Q(1,'Why will the increase hurt commuters?','their travel costs will rise','their trips become free','they will own more buses','Higher fares reduce money available for other uses.'),Q(1,'Which situation affects a family pocketbook?','a sharp rise in monthly bills','a bird changing feathers','a poem gaining rhythm','Pocketbook can represent a household budget.'),Q(1,'In “It is hard on the pocketbook,” what is hard?','the expense','the wallet’s material','the bus route','The phrase means financially burdensome.')]);
P('pod','From Middle English podde, probably a Germanic word for a seed case; precise origin uncertain.',C('pod.s1','botany','The pea pod split open, scattering round seeds across the table.','豌豆荚裂开，圆圆的种子散落在桌上。','pea pod split open','compound subject','A pod is the seed-containing case of certain plants.'),M('The pea pod opened and released a flock of birds.','The pea pod opened and released its seeds.','A plant pod contains seeds, not birds.','meaning'),[Q(1,'What spilled from the pea pod?','seeds','feathers','water pipes','A pod is a case containing seeds.'),Q(1,'Which plant part is a pod?','a seed case','a tree root','a flower petal','The source sense is a seed-containing case.'),Q(1,'What happened to the pod?','it split open','it turned into a bird','it carried a passenger','The sentence describes the case opening.'),Q(1,'Where might you find peas?','inside a pod','inside a feather','inside a plumb bob','Peas grow in seed pods.')]);
P('podcast','Coined in the early 2000s from iPod + broadcast; the device name became a general term for internet audio programs.',C('podcast.s1','media','The science podcast releases a new audio episode every Thursday.','这档科学播客每周四发布一期新的音频节目。','science podcast','noun modifier','The noun is an internet-published series of spoken audio.'),M('She listened to the podcast by reading a silent printed map.','She listened to the podcast through an audio player.','A podcast is spoken audio; a silent map is not an audio program.','meaning'),[Q(1,'What does the science podcast release?','an audio episode','a bus schedule','a bag of seeds','A podcast is a spoken audio program.'),Q(1,'How often is the episode released?','every Thursday','every century','only at sunrise','The example gives a weekly release day.'),Q(1,'Which item could be a podcast?','an online spoken interview series','a printed road atlas','a silent photograph','Podcasts are published audio programs.'),Q(1,'What does the coined word combine?','iPod and broadcast','plum and pod','phone and poem','Podcast was coined as a blend of iPod and broadcast.')]);
P('podium','From Latin podium, from Greek podion “little foot,” based on pous “foot”; it names a raised platform or stand.',C('podium.s1','public speaking','The conductor stepped onto the podium and raised her hands to cue the orchestra.','指挥走上指挥台，举起双手示意乐团开始。','stepped onto the podium','verb + preposition','The podium is the raised stand from which a speaker or conductor works.'),M('The conductor stood beneath the podium so the orchestra could see her clearly.','The conductor stood on the podium so the orchestra could see her clearly.','A podium is a raised stand; standing beneath it would defeat its purpose here.','meaning'),[Q(1,'Who stepped onto the podium?','the conductor','the orchestra’s audience','the ticket seller','A podium can be a raised stand for a conductor.'),Q(1,'Why did she raise her hands?','to cue the orchestra','to repair the podium','to count the tickets','The context says she signaled the musicians.'),Q(1,'Which object is a podium?','a raised stand','a seed case','a wall pipe','The noun names a platform or stand.'),Q(1,'Where did the conductor stand?','on the raised stand','under the audience seats','inside a violin','A podium elevates the conductor for visibility.')]);
P('poem','From Old French poeme and Latin poema, from Greek poiēma “something made,” based on poiein “make.”',C('poem.s1','literature','The poem arranged short lines around the image of a rain-darkened garden.','这首诗围绕雨后昏暗的花园意象排列短行。','the poem arranged short lines','noun subject','The core sense is a piece of writing in verse.'),M('The poem was a spreadsheet listing each customer’s address.','The poem used lines and imagery to describe the garden.','A spreadsheet is not a poem; the corrected sentence restores the literary sense.','meaning'),[Q(1,'What kind of work is the poem?','writing arranged in lines','a household invoice','a weather instrument','A poem is a literary work, often arranged in lines.'),Q(1,'What image organized the poem?','a rain-darkened garden','a metal plow','a bus engine','The example identifies its central image.'),Q(1,'Which feature is common in poems?','rhythm and imagery','pipe fittings','vote totals','Poems often use rhythm and imagery.'),Q(1,'What does the example say about its structure?','it uses short lines','it is a single spoken word','it is a seed case','The sentence explicitly mentions short lines.')]);
P('poet','From Old French poete and Latin poeta, from Greek poiētēs “maker,” based on poiein “make.”',C('poet.s1','literature','The poet read her new collection at the neighborhood library.','诗人在社区图书馆朗读了她的新诗集。','poet read her collection','subject + verb','A poet is a person who writes poetry.'),M('The poet repaired the burst water pipe using a wrench and sealant.','The plumber repaired the burst water pipe.','A poet writes poetry; plumbing is the plumber’s trade.','meaning'),[Q(1,'What does a poet do?','writes poetry','repairs water mains','pollinates flowers','A poet is a person who writes poems.'),Q(1,'Where did she read her collection?','at a neighborhood library','inside a reactor','under a bridge only','The example places the reading at the library.'),Q(1,'Which person is a poet?','someone who writes poems','someone who installs pipes','someone who measures votes','The defining work is writing poetry.'),Q(1,'What did the poet read?','her new collection','a plumbing manual only','a seed catalog','The sentence says she read her poetry collection.')]);
P('poetic','From Greek poiētikos “creative,” through Latin poeticus and French poétique; related to poem and poet.',C('poetic.s1','style','Her description of the fog as a “silver curtain” was vivid and poetic.','她把雾形容为“银色帷幕”，生动而富有诗意。','vivid and poetic','coordinated adjectives','Poetic can describe language with imaginative, lyrical quality.'),M('His poetic description was a plain list of numbers without imagery.','His poetic description compared the fog to a silver curtain.','Poetic language is imaginative or lyrical; the revised sentence supplies an image.','meaning'),[Q(1,'Why is “silver curtain” poetic?','it creates an imaginative image','it gives a bus timetable','it lists laboratory temperatures','The phrase uses figurative imagery.'),Q(1,'What does poetic describe here?','the style of her description','the weather instrument','the library building','Poetic modifies the imaginative wording.'),Q(1,'Which phrase sounds most poetic?','moonlight spilled across the roofs','temperature: 12 degrees','meeting starts at 8','The first phrase uses vivid imagery.'),Q(1,'What is a likely effect of poetic wording?','it creates a lyrical image','it states a bare number','it identifies a tool','Poetic language can be imaginative and expressive.')]);
P('poetry','From Old French poetrie and Latin poetria, from Greek poiētikē “poetic art,” based on poiētēs “maker.”',C('poetry.s1','literature','The course compares modern poetry from several countries and languages.','这门课程比较了多种国家和语言的现代诗歌。','compares modern poetry','mass noun object','Poetry is poems collectively or the art of writing them.'),M('The course studied poetry by comparing only the wiring diagrams of engines.','The course studied poetry by comparing poems from several traditions.','Engine diagrams are not poetry; the correction gives literary material.','meaning'),[Q(1,'What does the course compare?','poems from different traditions','plumbing systems','reactor fuels','Poetry means poems considered as a body of work.'),Q(1,'Which subject studies poetry?','literature','carpentry','meteorology','Poetry is a literary art.'),Q(1,'What can poetry mean besides a collection of poems?','the art of writing poems','a tool for checking walls','an allowance for children','Poetry can denote the art itself.'),Q(1,'Which is an example of poetry?','a collection of verse','a bus timetable','a chemical element','Poetry consists of poems or the art of composing them.')]);
P('poikilotherm','From Greek poikilos “varied” + thermē “heat”; coined in scientific terminology for an animal whose body temperature varies with surroundings.',C('poikilotherm.s1','biology','A lizard is a poikilotherm, so its body temperature changes with the surrounding air.','蜥蜴是变温动物，因此体温会随周围空气变化。','lizard is a poikilotherm','predicate noun','The noun names an animal without a constant internally regulated temperature.'),M('A poikilotherm keeps exactly the same body temperature in every environment.','A poikilotherm’s body temperature varies with its environment.','The defining feature is variable body temperature, not a fixed one.','meaning'),[Q(1,'How does a poikilotherm’s temperature behave?','it varies with the surroundings','it is always exactly 37°C','it equals the air pressure','The term names animals whose body temperature varies.'),Q(1,'Which animal might be a poikilotherm?','a lizard','a feather','a tree branch','The example identifies a lizard.'),Q(1,'What does the Greek element therm relate to?','heat','writing','sound','Therm comes from Greek for heat.'),Q(1,'Why did the lizard’s temperature change?','the surrounding air changed','it became a poem','it grew new feathers','Its body temperature follows environmental conditions.')]);
P('poikilothermic','Formed from poikilotherm with the adjective suffix -ic; Greek poikilos “varied” and thermē “heat” underlie the scientific term.',C('poikilothermic.s1','biology','The species is poikilothermic and relies on warm rocks to raise its body temperature.','这种动物是变温的，依靠温暖的岩石升高体温。','is poikilothermic','predicate adjective','The adjective means that body temperature varies with environmental heat.'),M('A poikilothermic reptile relies on warm rocks because its body temperature never responds to the environment.','A poikilothermic reptile relies on warm rocks to warm its body.','Poikilothermic animals respond to outside temperatures; they do not keep a fixed internal temperature.','meaning'),[Q(1,'Why does the animal bask on warm rocks?','to raise its body temperature','to make its feathers grow','to cool a metal pipe','A poikilothermic animal uses environmental heat.'),Q(1,'What does poikilothermic describe?','temperature varying with surroundings','constant internal temperature','a preference for cold food','The adjective names variable-temperature physiology.'),Q(1,'Which animal behavior fits the example?','basking to warm up','sweating to keep an exact temperature','growing a wool coat','Using warm rocks reflects environmental temperature dependence.'),Q(1,'What does the suffix -ic do in poikilothermic?','forms an adjective','marks a plural noun','forms a past-tense verb','The suffix creates the adjective from the scientific noun.')]);
P('point','From Old French point and Latin punctum “a prick, dot,” from pungere “to prick”; its senses extend from a mark to an idea or purpose.',[C('point.s1','discussion','The main point of her report was that the bridge needed urgent repairs.','她报告的核心要点是桥梁需要紧急维修。','main point of her report','of-phrase','This sense is a central idea or fact.'),C('point.s5','gesture','He pointed toward the exit so the visitors could find the street.','他指向出口，好让访客找到街道。','pointed toward the exit','verb + toward','The verb means direct a finger or object toward something.')],M('She pointed toward the exit by turning her back and indicating the opposite wall.','She pointed toward the exit with an outstretched hand.','Point toward means direct a gesture at the intended place.','meaning'),[Q(1,'What was the report’s main point?','the bridge needed urgent repairs','the office needed new curtains','the report had no subject','Point as a noun can mean the central idea.'),Q(5,'Where did he direct his gesture?','toward the exit','toward the ceiling fan only','toward the bridge foundations','Point toward means aim a gesture at a place.'),Q(1,'Which sentence uses point as an argument idea?','Her point was that the plan was costly.','She pointed at the map.','The needle had a sharp point.','The first example uses the “main idea” sense.'),Q(5,'Which action means to point?','aim a finger toward a sign','write a poem about a sign','hide the sign in a pocket','The verb means direct a finger or object toward something.')]);

P('pointed','From point + -ed; the adjective’s literal “having a point” sense is extended to direct, sharply expressed remarks.',C('pointed.s1','description','The pointed tip of the arrow fit neatly into the target’s center.','箭头尖端正好嵌入靶心。','pointed tip of the arrow','adjective + noun','The sense here is having a sharp end.'),M('The pointed arrow had a broad, completely blunt tip.','The pointed arrow had a sharp tip.','Pointed means having a point, not being blunt.','meaning'),[Q(1,'What did the arrow have?','a sharp tip','a rounded handle only','a flat side','Pointed describes an object with a sharp end.'),Q(1,'Which object is pointed?','a sharp pencil','a smooth ball','a flat plate','A pointed item has a sharp end.'),Q(1,'Where did the tip fit?','the target’s center','the pocket’s lining','the pod’s seeds','The example says it fit into the target center.'),Q(1,'Choose the opposite of pointed here.','blunt','sharp','tapered','Blunt means not sharply pointed.')]);
P('pointer','From point + -er, a suffix for a person or thing that points; the advisory sense develops from something that directs attention.',[C('pointer.s1','technology','The laser pointer marked the exact line on the screen.','激光指示器标出了屏幕上的确切一行。','laser pointer','noun modifier','The instrument sense names an object that indicates a location.'),C('pointer.s2','advice','One useful pointer from the editor was to shorten the opening paragraph.','编辑给出的一条有用建议是缩短开头段落。','pointer from the editor','of-phrase','The advisory sense is a practical hint or piece of advice.')],M('The editor gave a pointer by advising the writer to make the opening even longer, though it already rambled.','The editor gave a pointer by advising the writer to shorten the opening.','A pointer is useful guidance; the revised advice addresses the stated problem.','meaning'),[Q(1,'What did the laser pointer do?','indicated a line on the screen','measured the room temperature','printed the screen','A pointer can be an instrument for indicating a location.'),Q(2,'What was the editor’s pointer?','advice to shorten the opening','a laser device','a vote total','Pointer can mean a helpful piece of advice.'),Q(1,'Which object is a pointer?','a wand that indicates a place','a seed pod','a plumbing wrench','The tool sense is something that points.'),Q(2,'Which sentence uses pointer as advice?','One pointer is to label each chart.','The pointer glowed red on the screen.','The pointer was made of metal.','The first sentence offers a useful suggestion.')]);
P('pointillism','Coined in French from point “dot”; the art term names a Neo-Impressionist technique using small dots of color.',C('pointillism.s1','art','In pointillism, the painter placed tiny separate dots of pure color across the canvas.','点彩主义绘画中，画家在画布上排列细小、分离的纯色点。','in pointillism','prepositional phrase','The technique relies on dots that blend visually at a distance.'),M('The artist used pointillism by covering the canvas with long unbroken brush strokes.','The artist used pointillism by applying many tiny dots of color.','Pointillism is defined by dots, not continuous strokes.','meaning'),[Q(1,'What marks the pointillist technique?','tiny dots of color','long engraved lines','large paper cutouts','Pointillism uses small dots.'),Q(1,'How do the separate colors appear to mix?','the viewer’s eye blends them','the paint dissolves in water','the canvas moves','Optical blending is a feature of pointillism.'),Q(1,'Which painterly action best fits pointillism?','placing dots side by side','painting one solid black block','scraping off all pigment','The technique applies many small marks.'),Q(1,'What does the word pointillism refer to?','a painting technique','a type of podium','a voting method','It is a Neo-Impressionist art technique.')]);
P('pointillist','From French pointilliste, formed from pointillism and -ist for a practitioner; it identifies an artist using that method.',C('pointillist.s1','art','The pointillist painted the river with thousands of tiny blue and green marks.','这位点彩派画家用数千个蓝绿色小点描绘河流。','pointillist painted the river','noun subject','A pointillist is an artist who works in the pointillist manner.'),M('The pointillist painted the scene using only one smooth, unbroken stroke.','The pointillist built the scene from many tiny color marks.','The term names an artist whose technique uses dots.','meaning'),[Q(1,'Who is a pointillist?','an artist who paints with tiny dots','a person who studies voting','a worker who repairs pipes','Pointillist names a practitioner of pointillism.'),Q(1,'What did the artist use to depict the river?','many small blue and green marks','a single metal plate','a woolen blanket','The example describes dot-based color marks.'),Q(1,'Which style might a pointillist use?','separate dots that blend visually','one continuous pencil line only','a sculpture carved from ice','Pointillists use many separate color marks.'),Q(1,'What is the relationship between pointillist and pointillism?','an artist and the technique','a river and a fish','a tool and its handle','A pointillist practices pointillism.')]);
P('pointless','From point + -less “without”; it means having no purpose, value, or useful result.',C('pointless.s1','decision-making','Without reliable data, another round of guessing would be pointless.','没有可靠数据，再猜一轮也毫无意义。','would be pointless','predicate adjective','Pointless describes an action with no useful purpose or result.'),M('They called the pointless test essential because it reliably answered their question.','They called the pointless test useless because it could not answer their question.','Pointless means having no useful purpose; the corrected judgment follows the context.','meaning'),[Q(1,'Why would guessing be pointless?','there is no reliable data','the answer is already certain','the test is carefully designed','Pointless means unlikely to achieve a useful result.'),Q(1,'Which task is pointless in context?','repeating guesses without evidence','collecting accurate measurements','checking a verified source','The absence of data makes further guessing unhelpful.'),Q(1,'Choose the closest meaning of pointless.','useless','essential','accurate','An action with no purpose is pointless.'),Q(1,'What might make a debate pointless?','no one can act on its outcome','it helps settle a decision','it clarifies the evidence','Pointless means lacking a useful purpose.')]);
P('points','Plural of point; in scoring, it names the units accumulated in a game or test.',C('points.s1','sports','The team earned three points for the winning goal in the final minute.','球队在最后一分钟凭制胜进球拿下三分。','earned three points','verb + numeral object','Points are scoring units; the number depends on the rules of the game.'),M('The team scored three points but its score did not increase at all.','The team scored three points, increasing its score by three.','Scoring points adds to the team’s score.','meaning'),[Q(1,'What did the team earn?','three scoring units','three new players','three minutes of extra time','Points are units used to record a score.'),Q(1,'How did the team earn the points?','by scoring the winning goal','by changing its uniform','by moving the stadium','The example links the goal with the points.'),Q(1,'Which meaning of points fits the sentence?','score units','sharp tips','advice','The context is sports scoring.'),Q(1,'If a team gains points, what changes?','its score rises','the ball becomes smaller','the match is erased','Points contribute to a team’s score.')]);
P('poise','From Old French poise, based on Latin pensare “to weigh”; the idea of balanced weight developed into composure and graceful balance.',[C('poise.s1','demeanor','Even under questioning, the witness answered with remarkable poise.','即使受到盘问，证人回答时仍表现得异常镇定。','with remarkable poise','with-phrase','The composure sense is calm confidence under pressure.'),C('poise.s3','movement','The diver poised herself on the board before the final jump.','最后一跳前，跳水运动员在跳板上摆好姿势。','poised herself on the board','reflexive verb','As a verb, poise means hold oneself in a balanced, ready position.')],M('The witness showed poise by panicking and shouting over every question.','The witness showed poise by answering calmly under pressure.','Poise is composed self-control, not uncontrolled panic.','meaning'),[Q(1,'How did the witness respond?','calmly and confidently','by shouting in panic','by leaving the room','Poise is composure under pressure.'),Q(3,'What did the diver do before jumping?','held a balanced ready position','fell into the audience','removed the board','To poise oneself is to assume a balanced position.'),Q(1,'Which person shows poise?','a speaker who remains composed during questions','a speaker who loses control','a speaker who cannot stand','Poise means calm confidence.'),Q(3,'Which action uses poise as a verb?','She poised the vase on the narrow shelf.','She poise the vase yesterday.','She avoids the vase.','The verb can mean placing or holding something in balance.')]);
P('poised','Past participle of poise; the adjective describes composure or readiness for action.',C('poised.s1','performance','The poised pianist waited silently for the conductor’s cue.','沉着的钢琴家静静等待指挥的提示。','poised pianist','adjective before noun','Here poised describes calm, controlled behavior.'),M('The poised pianist trembled, shouted, and rushed onto the stage without waiting.','The poised pianist waited calmly for the conductor’s cue.','Poised describes composure or readiness, not uncontrolled haste.','meaning'),[Q(1,'How did the pianist wait?','calmly and with control','in a noisy panic','by leaving before the cue','Poised means composed and controlled.'),Q(1,'Which person seems poised?','a speaker who answers calmly','a person who loses control','a runner who trips repeatedly','Poised describes composure.'),Q(1,'What was the pianist waiting for?','the conductor’s cue','a bus ticket','the piano to become a poem','The sentence names the conductor’s signal.'),Q(1,'Choose a close synonym for poised here.','composed','confused','reckless','The adjective means calm and self-possessed.')]);
P('poison','From Old French poison, from Latin potionem “a drink,” later a harmful drink or substance.',[C('poison.s1','safety','The label warns that the liquid is poison and must be kept away from children.','标签警告这种液体有毒，必须放在儿童接触不到的地方。','liquid is poison','predicate noun','The noun names a harmful substance.'),C('poison.s3','relationships','Constant suspicion poisoned the friendship until neither person trusted the other.','不断的猜疑毒化了这段友谊，最终两人都不再信任对方。','poisoned the friendship','figurative verb + object','The figurative verb means harm or corrupt a relationship.')],M('The label says the poison is safe to drink in large quantities.','The label warns that the poison is dangerous if swallowed.','Poison is a harmful substance and should not be described as safe to ingest.','meaning'),[Q(1,'What does the warning label identify?','a harmful liquid','a harmless drink','a food recipe','Poison is a substance that can seriously harm or kill.'),Q(3,'What happened to the friendship?','suspicion damaged it','suspicion strengthened trust','the two people never met','Poison can figuratively damage relationships.'),Q(1,'What should people do with poison?','keep it away from children','pour it into a drinking cup','store it beside snacks','The label warns against access and ingestion.'),Q(3,'Which sentence uses poison figuratively?','Rumors poisoned their cooperation.','The bottle contains poison.','The warning lists a poison.','The first sentence means rumors harmed the relationship.')]);
P('poisonous','From poison + -ous, an adjective suffix meaning “having the nature of”; it means containing or producing poison.',C('poisonous.s1','nature','The guide warned hikers not to eat the poisonous berries beside the trail.','向导提醒徒步者不要吃小径旁的有毒浆果。','poisonous berries','adjective before noun','The adjective describes something containing or producing poison.'),M('The poisonous berries are safe to eat because their toxins are harmless.','The poisonous berries can harm anyone who eats them.','Poisonous means containing poison, so the berries are not safe to eat.','meaning'),[Q(1,'Why should hikers avoid the berries?','they contain poison','they are too cold','they are made of stone','Poisonous describes something that can cause harm through poison.'),Q(1,'Which plant has poisonous berries?','one whose berries contain toxins','one whose berries are blue','one growing beside a trail','Poisonous means toxic, not merely colorful or wild.'),Q(1,'What did the guide do?','warned hikers not to eat them','served the berries as lunch','planted them in a cup','The sentence states the safety warning.'),Q(1,'Choose the closest meaning of poisonous.','toxic','edible','nutritious','Poisonous means harmful because of poison.')]);
P('poke','From Middle English poken, probably a Germanic word meaning to thrust or push; poke fun at is a later idiom.',[C('poke.s1','action','He poked a hole in the soil with a stick before planting the seed.','种种子前，他用棍子在土里戳了个洞。','poked a hole','verb + object','The basic verb sense is a quick push with a finger or object.'),C('poke.s2','idiom','The older students promised not to poke fun at the new pupil’s accent.','高年级学生答应不再取笑新同学的口音。','poke fun at','fixed idiom','In poke fun at, poke means make fun of someone.')],M('The students poked fun at the new pupil by praising her accent sincerely.','The students poked fun at the new pupil by mocking her accent.','Poke fun at means tease or mock, not sincerely praise.','meaning'),[Q(1,'How did he make a hole?','by pushing a stick into the soil','by pouring water on it','by polishing the seed','Poke means push quickly into something.'),Q(2,'What does “poke fun at” mean?','make fun of','protect from rain','plant beside','The idiom means tease or mock.'),Q(1,'Which action is a poke?','nudging a button with a finger','carrying a table','watching a film','A poke is a quick push.'),Q(2,'Which sentence uses the idiom correctly?','They poked fun at his silly hat.','They poked fun into the soil.','They poked fun the window.','Poke fun at is the fixed construction for teasing.')]);
P('polar','From Latin polaris, based on polus “end of an axis,” from Greek polos “pivot or axis”; it can describe Earth’s poles or opposite extremes.',[C('polar.s1','geography','A polar research station must prepare for months of darkness in winter.','极地科考站必须为冬季数月的黑暗做好准备。','polar research station','adjective before noun','The geographic sense relates to the North or South Pole.'),C('polar.s2','opinions','The two candidates offered polar views on how much the government should spend.','两位候选人对政府应支出多少持截然相反的观点。','polar views','adjective before noun','The figurative sense means completely opposed.')],M('Their polar views were nearly identical on every question.','Their polar views were completely opposed on the central issue.','Polar in this figurative sense describes opposite extremes.','meaning'),[Q(1,'What does polar describe in the station example?','a region near Earth’s poles','a tropical island','a desert equator','Polar has a geographic sense relating to the poles.'),Q(2,'How did the candidates’ views compare?','they were completely opposed','they were identical','they were both unstated','Polar views are strongly opposite.'),Q(1,'Which place is polar?','a research base near the South Pole','a beach near the equator','a city in the tropics','The adjective can relate to the North or South Pole.'),Q(2,'Which pair has polar differences?','two completely opposite positions','two nearly identical opinions','two copies of one map','The figurative sense describes opposites.')]);
P('polarity','From polar + -ity, based on Latin polaris and polus “axis”; the word names a condition of having two opposed poles.',C('polarity.s1','physics','The magnet’s polarity determined which end attracted the north-seeking compass needle.','磁体的极性决定了哪一端会吸引指南针的指北针。','magnet’s polarity','possessive subject','Polarity is the condition of having opposed poles or directions.'),M('The magnet’s polarity meant it had no north or south pole at all.','The magnet’s polarity described its opposed north and south poles.','Polarity refers to opposed poles, not their absence.','meaning'),[Q(1,'What did the magnet’s polarity determine?','which end attracted the needle','the magnet’s color','the needle’s length','Polarity concerns opposed magnetic ends.'),Q(1,'Which object has polarity?','a magnet with north and south poles','a round ball with no orientation','a poem with four lines','A magnet’s opposed poles illustrate polarity.'),Q(1,'What does polarity mean here?','the condition of having opposed poles','a single uniform pole','a type of metal','Polarity names a two-pole condition.'),Q(1,'Why did the compass needle respond?','opposed magnetic poles interact','the magnet contained water','the compass was a plow','Magnetic polarity governs attraction and repulsion.')]);
P('polarize','From polar + -ize, ultimately Latin polus and Greek polos “axis”; the verb means to create or intensify opposed poles.',C('polarize.s1','public debate','The proposal polarized the committee into two sharply opposed camps.','这项提案使委员会分裂成两个截然对立的阵营。','polarized the committee','verb + object','The social sense means divide opinion into opposing extremes.'),M('The proposal polarized the committee by making every member agree completely.','The proposal polarized the committee by dividing members into opposing camps.','Polarize means create opposing sides, not unanimous agreement.','meaning'),[Q(1,'What effect did the proposal have?','divided the committee into opposed camps','made the committee unanimous','ended the committee’s meeting early','To polarize is to split into opposing positions.'),Q(1,'Which issue could polarize a group?','a divisive proposal','a universally accepted spelling','a shared lunch menu','A divisive question can create opposing camps.'),Q(1,'Choose the closest meaning of polarized here.','divided sharply','united fully','forgotten','The sentence describes a sharp division.'),Q(1,'What formed after the committee was polarized?','two opposing camps','one identical opinion','a new building','Polarization creates opposing groups or views.')]);
P('pole','From Latin polus and Greek polos “axis or pivot”; it names a long rod, a geographic pole, or one of two extremes.',[C('pole.s1','equipment','The tent’s central pole held the canvas roof above the campers.','帐篷中央的杆子支撑着露营者头顶的帆布顶。','central pole','noun subject','This sense is a long rod or support.'),C('pole.s2','geography','The expedition planned to reach the South Pole in early summer.','探险队计划在初夏抵达南极点。','South Pole','proper name','The geographic sense is an end of Earth’s axis.')],M('The tent roof was supported by a soft feather pole.','The tent roof was supported by a sturdy wooden pole.','A support pole is a rigid rod, not a feather.','meaning'),[Q(1,'What did the tent pole support?','the canvas roof','the expedition’s food','the ground beneath the tent','A pole can be a rod supporting a structure.'),Q(2,'Where did the expedition plan to go?','the South Pole','the equator','the North Atlantic','The geographic sense names an end of Earth’s axis.'),Q(1,'Which item is a pole?','a long rod','a seed case','a feather coat','Pole can mean a long round piece of wood or metal.'),Q(2,'What is the South Pole?','one end of Earth’s axis','a mountain on the equator','a magnetic compass needle','It is the southern geographic pole.')]);
P('polestar','From pole + star; the name Polaris (the Pole Star) is used for navigation and metaphorically for a guiding principle.',C('polestar.s1','navigation','For generations, sailors used the polestar to estimate their direction in the northern sky.','数代水手借助北极星估测自己在北半球的方向。','used the polestar','verb + object','The literal sense is Polaris, the star near the north celestial pole.'),M('The sailors used the polestar because it circled unpredictably around the southern horizon.','The sailors used the polestar as a steady guide in the northern sky.','The polestar is Polaris near the north celestial pole, not a southern star.','meaning'),[Q(1,'Which star is meant by polestar?','Polaris','Sirius','the Sun','Polestar is another name for Polaris.'),Q(1,'Why did sailors use it?','to estimate direction','to measure water depth','to predict a harvest','Polaris has long served as a navigational guide.'),Q(1,'Where does the literal polestar appear?','near the north celestial pole','under the ocean','at the center of Earth','The name refers to Polaris in the northern sky.'),Q(1,'What can polestar mean figuratively?','a guiding principle','a hidden danger','a cooking method','A guiding star becomes a metaphor for direction.')]);
P('police','From French police, via Latin politia and Greek politeia “state, government”; the institutional sense concerns maintaining public order.',[C('police.s1','public safety','The police arrived quickly after the shop owner called to report a break-in.','店主报警称有人闯入后，警察很快赶到。','the police arrived','collective noun','Police can refer to officers as a group.'),C('police.s3','regulation','Inspectors police the market to make sure vendors follow safety rules.','检查员监督市场，确保摊贩遵守安全规定。','police the market','verb + object','As a verb, police means maintain order or enforce rules.')],M('Inspectors police the market by ignoring every safety rule violation.','Inspectors police the market by enforcing its safety rules.','To police a place is to enforce rules there.','meaning'),[Q(1,'Who arrived after the break-in report?','the police','the vendors','the musicians','Police can mean the officers as a group.'),Q(3,'What do inspectors do when they police the market?','enforce safety rules','sell fruit','repair the roof','The verb means supervise and enforce rules.'),Q(1,'Which phrase refers to the organization?','the police issued a statement','a police officer wrote a poem','a poll measured support','Police can denote the law-enforcement body.'),Q(3,'Which action is to police a rule?','monitor whether people obey it','erase it from a book','memorize its spelling','The verb sense is to maintain order or enforce rules.')]);
P('policeman','Compound of police + man, used for a male police officer; modern usage often favors the gender-neutral police officer.',C('policeman.s1','public safety','The policeman directed traffic around the flooded intersection.','男警察在被水淹的十字路口指挥交通。','policeman directed traffic','noun subject','The source sense is a man who serves as a police officer.'),M('The policeman directed traffic by telling every driver to ignore the detour.','The policeman directed traffic around the flooded intersection.','Directing traffic means guiding drivers safely, not telling them to ignore a detour.','meaning'),[Q(1,'What did the policeman direct?','traffic','the orchestra','a committee vote','A policeman is a male police officer.'),Q(1,'Where did he direct it?','around a flooded intersection','through a closed tunnel','into a river','The sentence identifies the detour around flooding.'),Q(1,'Which description matches policeman?','a man serving as a police officer','a person who writes poems','a person who repairs pipes','The source definition identifies a male officer.'),Q(1,'What is a common gender-neutral alternative?','police officer','policewoman only','pollster','Police officer avoids specifying gender.')]);
P('policewoman','Compound of police + woman, naming a woman who serves as a police officer.',C('policewoman.s1','public safety','The policewoman interviewed witnesses after the bicycle was stolen.','自行车被盗后，女警察询问了目击者。','policewoman interviewed witnesses','noun subject','The source sense identifies a woman police officer.'),M('The policewoman was a man who served as a police officer.','The policewoman was a woman who served as a police officer.','Policewoman specifically names a woman serving as a police officer.','meaning'),[Q(1,'Who interviewed the witnesses?','a woman police officer','a poet','a pollinator','Policewoman names a female police officer.'),Q(1,'Why were witnesses interviewed?','a bicycle had been stolen','a concert was postponed','a pipe had burst','The context ties the interview to the theft.'),Q(1,'Which person is a policewoman?','a woman serving as an officer','a woman who writes poems','a woman who sells tickets','The source sense is a woman police officer.'),Q(1,'Which neutral term can also describe her role?','police officer','plumage','pocketbook','Police officer is a gender-neutral job title.')]);

P('policy','From French policie and Latin politia “government or public administration,” based on Greek politeia “citizenship, constitution.”',[C('policy.s1','government','The city adopted a policy to publish all contract awards online.','市政府通过了一项政策，要求在线公布所有合同授予结果。','adopted a policy','verb + object','This sense is an agreed plan of action for an organization.'),C('policy.s3','insurance','Read the insurance policy carefully to see which repairs it covers.','仔细阅读保险单，看看它承保哪些维修。','insurance policy','noun modifier','The document sense is a written insurance contract.')],M('The city’s policy required online publication but prohibited anyone from publishing the awards.','The city’s policy required the awards to be published online.','A policy is a plan or rule; this one should not contradict its stated purpose.','meaning'),[Q(1,'What did the city adopt?','a plan to publish contract awards','a new insurance claim','a set of poems','Policy can mean an organization’s agreed plan of action.'),Q(3,'What should the reader check in the insurance policy?','which repairs are covered','which poems are insured','where the city holds elections','A policy can be a written insurance contract.'),Q(1,'Which item is a school policy?','a rule about attendance','a student’s pocket','a weather report','An institutional policy sets a plan or rule.'),Q(3,'Which policy contains coverage terms?','an insurance contract','a government campaign','a personal preference only','The document sense refers to an insurance policy.')]);
P('polio','Shortened from poliomyelitis, a medical name built from Greek polios “gray” + myelos “marrow” + -itis “inflammation.”',C('polio.s1','medicine','Vaccination campaigns have greatly reduced cases of polio, a viral disease that can paralyze muscles.','疫苗接种运动大大减少了脊髓灰质炎病例；这种病毒性疾病可能使肌肉麻痹。','cases of polio','of-phrase','Polio is poliomyelitis, an infection that may cause paralysis.'),M('Polio is a harmless skin rash that never affects nerves or muscles.','Polio is a viral infection that can damage nerves and paralyze muscles.','Polio can be serious and may cause paralysis; it is not merely a harmless rash.','meaning'),[Q(1,'What can polio do?','paralyze muscles','strengthen bones instantly','cause a harmless sun tan','Polio may damage motor nerves and cause paralysis.'),Q(1,'What kind of illness is polio?','a viral infection','a fungal plant disease','a type of broken bone','The source sense identifies it as a viral disease.'),Q(1,'What did vaccination campaigns reduce?','cases of polio','the number of muscles','all viruses everywhere','The example says vaccination reduced polio cases.'),Q(1,'Which description best fits polio?','a disease that can affect movement','a harmless skin color','a joint of an insect','Polio can affect muscles and movement.')]);
P('polish','From Polish polir, ultimately Latin polire “to make smooth”; separate noun/adjective uses are distinguished by stress and capitalization.',[C('polish.s1','craft','She polished the brass handle until it reflected the window light.','她把黄铜把手擦亮，直到它映出窗边的光。','polished the brass handle','verb + object','The verb means rub a surface to make it smooth or shiny.'),C('polish.s2','writing','Before submitting the essay, he polished its conclusion for clarity.','提交论文前，他润色了结尾，使表达更清晰。','polished its conclusion','verb + object','The figurative verb means improve writing or a skill.'),C('polish.s3','household','A little furniture polish restored the table’s shine.','少量家具上光剂就恢复了桌子的光泽。','furniture polish','noun modifier','The noun can mean a substance used to make surfaces shine.')],M('She polished the essay by making its conclusion less clear and more confusing.','She polished the essay by making its conclusion clearer and more concise.','To polish writing is to improve it, not make it less clear.','meaning'),[Q(1,'What happened to the brass handle?','it became shiny from rubbing','it was rewritten','it was painted with words','Polish as a verb can make a surface smooth and shiny.'),Q(2,'What did he polish before submitting?','the essay’s conclusion','the brass handle','the furniture polish bottle','The figurative verb means refine writing.'),Q(3,'What restored the table’s shine?','furniture polish','a poem','a policy','Polish as a noun names a shining substance.'),Q(2,'Which action polishes an essay?','revising it for clarity','covering it in varnish','washing it in water','The writing sense means improve style or quality.')]);
P('polished','From the past participle of polish; it describes a surface made shiny or a manner made refined through practice.',C('polished.s1','performance','After months of rehearsal, the band delivered a polished performance.','经过数月排练，乐队呈现了一场娴熟流畅的演出。','polished performance','adjective before noun','The figurative adjective means refined and skillfully executed.'),M('The band’s polished performance was full of missed cues and unfinished passages.','The band’s polished performance was smooth and well rehearsed.','Polished in this sense means skillful and refined, not full of errors.','meaning'),[Q(1,'What did rehearsal produce?','a refined performance','a broken instrument','an unfinished song','Polished can mean skillfully refined.'),Q(1,'Which performance sounds polished?','one delivered smoothly after practice','one stopped after every note','one without a tune','The adjective describes a practiced, refined result.'),Q(1,'What does polished mean in the example?','well rehearsed and skillful','covered in furniture wax','rough and uncertain','It describes the band’s smooth delivery.'),Q(1,'Which item can be literally polished?','a brass surface','a spoken performance only','a committee policy','The literal sense is made shiny by rubbing.')]);
P('polite','From Middle French poli “polished, refined,” from Latin polire “to polish”; figurative refinement developed into courteous behavior.',[C('polite.s1','manners','The clerk was polite and thanked each customer for waiting.','店员彬彬有礼，感谢每位顾客耐心等候。','was polite','linking verb + adjective','The basic sense is showing respect and good manners.'),C('polite.s2','social interaction','They exchanged a polite greeting but did not stop to talk.','他们客气地打了招呼，却没有停下来交谈。','polite greeting','adjective before noun','Polite can describe formal courtesy without warmth or closeness.')],M('The clerk was polite by insulting each customer as they waited.','The clerk was polite by thanking each customer for waiting.','Insults are discourteous; thanking people is the polite action in this context.','meaning'),[Q(1,'How did the clerk behave?','with good manners','with open insults','with no response at all','Polite means showing respect and courtesy.'),Q(2,'What kind of greeting did they exchange?','courteous but not intimate','angry and abusive','a long personal conversation','A polite greeting can be formal rather than warm.'),Q(1,'Which action is polite?','thanking someone for waiting','mocking them for asking','pushing ahead in line','Courtesy includes respectful behavior.'),Q(2,'Why might a greeting be merely polite?','it is courteous but not close','it is an insult','it is a legal contract','The second sense allows formal, distant courtesy.')]);
P('politely','From polite + adverb suffix -ly; it means in a courteous or well-mannered way.',C('politely.s1','conversation','She politely declined the invitation and thanked the host for asking.','她礼貌地谢绝了邀请，并感谢主人相邀。','politely declined','adverb modifying verb','The adverb describes the courteous manner of declining.'),M('He politely thanked the host by calling the invitation stupid.','He politely thanked the host for the invitation.','Calling an invitation stupid is rude, not polite.','grammar'),[Q(1,'How did she decline?','courteously','angrily','without understanding the offer','Politely describes a courteous manner.'),Q(1,'Which sentence uses politely correctly?','He politely asked to borrow the book.','He politely shouted an insult.','He politely ignored every greeting.','The first action is courteous.'),Q(1,'What did she do after declining?','thanked the host','broke the invitation','changed the date without asking','The context includes thanks as a courteous gesture.'),Q(1,'Which word does politely modify in the example?','declined','invitation','host','The adverb modifies the verb declined.')]);
P('politeness','From polite + -ness, a noun suffix expressing a quality or state; it names courteous behavior.',C('politeness.s1','social behavior','The receptionist’s politeness put nervous visitors at ease.','接待员的礼貌让紧张的访客放松下来。','receptionist’s politeness','possessive noun subject','Politeness is respectful and considerate behavior.'),M('Her politeness consisted of shouting at each visitor and refusing to listen.','Her politeness consisted of greeting each visitor respectfully.','Politeness means courteous behavior, not hostility.','meaning'),[Q(1,'What put visitors at ease?','the receptionist’s courtesy','a loud argument','a broken desk','Politeness means respectful behavior.'),Q(1,'Which action shows politeness?','listening without interrupting','mocking a visitor','blocking the doorway','Courtesy includes consideration for others.'),Q(1,'What does -ness do in politeness?','forms a noun for a quality','forms a past-tense verb','marks plural','The suffix creates a quality noun from polite.'),Q(1,'Which word is closest in meaning to politeness?','courtesy','hostility','carelessness','Politeness and courtesy both concern good manners.')]);
P('politic','From Greek politikos “of citizens or the state,” via Latin politicus and French politique; the current adjective means tactful or expedient.',C('politic.s1','diplomacy','It was politic to thank both teams before discussing the disputed result.','讨论有争议的结果前，先感谢双方是明智得体的做法。','was politic to thank','predicate adjective + infinitive','Politic here means prudent and well judged in the circumstances.'),M('It was politic to insult both teams before trying to calm the dispute.','It was politic to thank both teams before discussing the dispute.','A politic choice is prudent and tactful, not needlessly provocative.','meaning'),[Q(1,'Why was thanking both teams politic?','it was tactful in a tense situation','it guaranteed a victory','it ended the discussion before it began','Politic means judicious or expedient.'),Q(1,'Which action is politic during a dispute?','acknowledging both sides respectfully','insulting each side','publishing rumors','A politic action is carefully judged for the situation.'),Q(1,'Choose a close meaning of politic.','prudent','reckless','irrelevant','The adjective means wise or expedient.'),Q(1,'What makes an action politic?','it is well judged for the circumstances','it concerns a particular election only','it is always popular','The example uses the tactful, prudent sense.')]);
P('political','From Greek politikos “of citizens or the state,” through Latin politicus; it relates to government, public affairs, or party activity.',[C('political.s1','government','The library hosted a political debate about housing and public transport.','图书馆举办了一场关于住房和公共交通的政治辩论。','political debate','adjective before noun','The adjective relates to government and public affairs.'),C('political.s2','parties','The mayor’s political campaign focused on winning support from local voters.','市长的政治竞选活动着重争取当地选民的支持。','political campaign','adjective before noun','It can also describe participation in party politics.')],M('The political debate concerned only the color of one private desk and no public issue.','The political debate concerned housing and public transport policy.','Political in this context concerns government or public affairs.','meaning'),[Q(1,'What did the debate concern?','housing and public transport','a private desk’s paint only','bird feathers','Political can relate to public affairs.'),Q(2,'What was the mayor trying to win?','support from local voters','a poetry prize','a chemistry medal','The campaign is party-political activity.'),Q(1,'Which issue is political?','a city’s housing policy','a person’s breakfast','a bird’s plumage','Government decisions about housing are public affairs.'),Q(2,'What does political modify in “political campaign”?','campaign','voters','support','The adjective describes a campaign in party politics.')]);
P('politically','From political + adverb suffix -ly; it means with regard to politics, government, or power.',C('politically.s1','public affairs','The bridge plan was politically difficult because residents disagreed about its cost.','这项桥梁计划在政治上很棘手，因为居民对成本意见不一。','politically difficult','adverb modifying adjective','Politically frames the difficulty in terms of public opinion or power.'),M('The bridge plan was politically difficult because it had no connection to public opinion or government.','The bridge plan was politically difficult because public opinion was divided.','Politically describes an issue’s relation to public affairs or support.','meaning'),[Q(1,'Why was the plan politically difficult?','residents disagreed about its cost','the bridge was made of paper','the team won a game','The issue involved public opinion.'),Q(1,'What does politically modify?','difficult','bridge','residents','The adverb modifies the adjective difficult.'),Q(1,'Which issue is politically sensitive?','a contested government spending plan','a private breakfast choice','a bird’s feather color','Political sensitivity concerns public decisions and opinion.'),Q(1,'Choose the closest meaning of politically here.','in terms of public affairs','in terms of chemistry','in terms of music','The adverb refers to the public and political dimension.')]);
P('politician','From politic + -ian, an agent/person suffix; Greek politikos “of citizens or the state” underlies the political root.',C('politician.s1','government','The politician answered questions from constituents at a town meeting.','这位政治人物在镇民大会上回答选民的问题。','politician answered questions','noun subject','A politician is a person who works in politics.'),M('The politician answered constituents’ questions by repairing their leaking pipes.','The plumber repaired the constituents’ pipes; the politician answered their questions.','A politician works in politics; pipe repair is a plumber’s trade.','meaning'),[Q(1,'Who answered constituents at the meeting?','a person working in politics','a plumber','a pollinator','A politician is someone engaged in politics.'),Q(1,'Whose questions did the politician answer?','constituents’','the orchestra’s','the plants’','Constituents are the people represented by an elected official.'),Q(1,'Where did the meeting take place?','at a town meeting','inside a reactor','on a ferry route','The sentence states the setting.'),Q(1,'Which task best fits a politician?','discussing public policy','repairing a water pipe','pollinating a flower','Politicians work on political and public affairs.')]);
P('politics','From Greek politika, “affairs of the cities,” the plural of politikos; the word covers government, opinions, and organizational power plays.',[C('politics.s1','government','She studies politics to understand how laws and public budgets are made.','她学习政治学，以了解法律和公共预算如何制定。','studies politics','verb + object','This sense concerns governing and public affairs.'),C('politics.s3','organizations','Office politics made it hard for the two teams to share credit.','办公室里的权力角逐让两个团队难以共享功劳。','office politics','noun modifier','The informal sense is power tactics within an organization.')],M('Office politics helped the teams cooperate openly and share credit without any maneuvering.','Office politics made the teams compete for influence and credit.','Office politics refers to internal power tactics, often complicating cooperation.','meaning'),[Q(1,'What does she study?','how laws and budgets are made','how feathers grow','how to repair pipes','Politics can mean the work of governing.'),Q(3,'What made sharing credit difficult?','internal power tactics','a lack of office chairs','a broken podium','Office politics describes power maneuvering inside an organization.'),Q(1,'Which topic belongs to politics?','public budgeting','plum ripening','plumbing joints','Politics concerns government and public affairs.'),Q(3,'What does office politics mean here?','power struggles within a workplace','an election for national office','the study of grammar','The example uses the organizational sense.')]);
P('poll','From Middle English pol “head, person”; a poll was originally a head count, later a vote, survey, or canvass.',[C('poll.s1','research','The poll asked 800 residents whether they supported the new park.','这项民调询问了800名居民是否支持新公园。','poll asked residents','verb + object','As a noun, a poll is a survey of people’s opinions.'),C('poll.s2','elections','Voters went to the polls early to avoid the afternoon queues.','选民早早去投票，以避开下午的队伍。','went to the polls','fixed phrase','The polls can refer to the act or place of voting.')],M('The poll asked 800 residents but recorded no answers from any of them.','The poll asked 800 residents and recorded their answers.','A poll gathers responses from people; a survey with no responses cannot report their views.','meaning'),[Q(1,'What did the poll ask residents?','whether they supported the park','whether they could repair a pipe','whether they liked a poem','A poll surveys people’s opinions.'),Q(2,'Why did voters go early to the polls?','to avoid queues','to plant a garden','to hear a podcast','The polls phrase refers to voting.'),Q(1,'Which activity is a poll?','asking a sample about its views','counting tree rings','polishing a table','A poll gathers opinions from many people.'),Q(2,'What happens at the polls?','people cast votes','people buy pocket money','people read plumage','Polls may refer to voting in an election.')]);
P('pollen','From Middle French pollen and Latin pollen “fine flour, dust”; in botany, the fine grains carry male reproductive cells in seed plants.',C('pollen.s1','botany','Bees carried pollen from one blossom to another as they searched for nectar.','蜜蜂在寻找花蜜时把花粉从一朵花带到另一朵花。','carried pollen','verb + object','Pollen is the fine powder involved in plant fertilization.'),M('The bees carried pollen from one blossom to another by transporting the tree’s roots.','The bees carried pollen between blossoms on their bodies.','Pollen is flower dust; roots are below ground and are not carried between blossoms.','meaning'),[Q(1,'What did the bees carry?','fine flower grains','tree roots','bird feathers','Pollen is fine powder produced by flowers.'),Q(1,'Where did the pollen go?','from one blossom to another','from the roots to a pocket','from the river to a podium','The example describes transfer between flowers.'),Q(1,'What role does pollen play?','it enables plant fertilization','it repairs stems','it stores animal food','Pollen carries the male reproductive cells.'),Q(1,'Which item is pollen?','powder from a flower','a hard seed case','a bird’s feather','The source sense defines pollen as flower powder.')]);
P('pollinate','From pollen + -ate, a verb-forming suffix; it means transfer pollen to a receptive part of a flower.',C('pollinate.s1','botany','A brush can pollinate greenhouse tomatoes when insects cannot reach the flowers.','昆虫无法接触花朵时，可以用刷子给温室番茄授粉。','pollinate greenhouse tomatoes','verb + object','Pollinate means transfer pollen so fertilization can occur.'),M('The gardener pollinated the tomatoes by removing every grain of pollen from their flowers.','The gardener pollinated the tomatoes by brushing pollen onto their flowers.','Pollination transfers pollen to the receptive flower; removing it prevents that process.','meaning'),[Q(1,'What did the brush do?','transferred pollen to flowers','removed the tomato roots','watered the leaves only','To pollinate is to transfer pollen.'),Q(1,'Why use a brush in the greenhouse?','insects could not reach the flowers','the tomatoes had no stems','the soil was frozen solid','The brush substitutes for an unavailable insect pollinator.'),Q(1,'What is the goal of pollination?','enable fertilization and seed formation','polish the fruit','cool the greenhouse','Pollen transfer allows fertilization.'),Q(1,'Which action pollinates a flower?','placing pollen on its receptive part','cutting off all its roots','covering it with paint','Pollination occurs when pollen reaches the receptive flower part.')]);
P('pollination','From pollinate + -ion, a noun suffix for an action or process; pollinate derives from pollen.',C('pollination.s1','botany','Successful pollination allowed the orchard’s apple trees to set fruit.','成功传粉后，果园的苹果树得以结果。','successful pollination','noun subject','Pollination is the transfer of pollen to a flower’s receptive part.'),M('Pollination occurred after all pollen was kept away from the flowers.','Pollination occurred when pollen reached the receptive parts of the flowers.','Pollination requires pollen transfer to a flower.','meaning'),[Q(1,'What followed successful pollination?','the trees set fruit','the branches became metal','the flowers stopped existing instantly','Pollination can lead to fertilization and fruit.'),Q(1,'What is pollination?','transfer of pollen to a flower','a method of polishing wood','a type of insect nest','The noun names the pollen-transfer process.'),Q(1,'Which condition helps pollination?','pollen reaching a receptive flower part','keeping pollen away from every flower','removing every blossom','Pollen must reach the receptive parts.'),Q(1,'Which word names the process, not the action verb?','pollination','pollinate','pollinator','Pollination is the noun form of the process.')]);
P('pollinator','From pollinate + -or, an agent suffix; it names an organism or other agent that transfers pollen.',C('pollinator.s1','ecology','The bat is an important pollinator for several night-blooming plants.','蝙蝠是几种夜间开花植物的重要传粉媒介。','important pollinator','noun complement','A pollinator carries pollen between flowers.'),M('The bat was a pollinator because it prevented all pollen from reaching flowers.','The bat was a pollinator because it carried pollen between flowers.','Pollinators transfer pollen; blocking its transfer would prevent pollination.','meaning'),[Q(1,'What role does the bat play?','it transfers pollen','it makes flowers into rocks','it eats the tree roots','A pollinator carries pollen between flowers.'),Q(1,'When do these plants bloom?','at night','only under water','in winter beneath ice','The example specifies night-blooming plants.'),Q(1,'Which animal can be a pollinator?','a bee visiting flowers','a fish far from plants','a stone in a field','Many insects and some other animals pollinate plants.'),Q(1,'What distinguishes a pollinator from pollen?','the pollinator carries it','the pollinator is the powder itself','the pollinator is a flower petal','A pollinator is the agent that transfers pollen.')]);
P('pollutant','From pollute + -ant, an agent or substance suffix; it names material that causes pollution.',C('pollutant.s1','environment','The inspectors traced the oily pollutant in the river to a leaking storage tank.','检查人员追查河里的油性污染物，发现它来自一个泄漏的储罐。','oily pollutant','adjective before noun','A pollutant is a harmful substance released into the environment.'),M('The pollutant cleaned the river by adding more toxic waste.','The pollutant contaminated the river after leaking from the tank.','A pollutant causes contamination; it does not clean the water.','meaning'),[Q(1,'What did inspectors trace?','an oily contaminant','a bird’s nest','a bridge repair','A pollutant is a substance causing pollution.'),Q(1,'Where did it come from?','a leaking storage tank','a clean spring','a flower’s pollen sac','The sentence identifies the leaking tank.'),Q(1,'Which substance is a pollutant?','toxic waste entering a river','clean rainwater','a polished surface','Pollutants harm or contaminate the environment.'),Q(1,'What does the suffix -ant signal here?','a substance that does something','a past-tense action','a plural verb','Pollutant names the agent or substance causing pollution.')]);
P('pollute','From Latin polluere “to defile or soil,” from por- “forth” + luere “to wash”; it can harm the environment or figuratively corrupt.',[C('pollute.s1','environment','Oil from the damaged tanker polluted the coastal water and killed fish.','受损油轮泄漏的石油污染了沿海水域并导致鱼类死亡。','polluted the coastal water','verb + object','The literal sense makes air, water, or soil dirty with harmful substances.'),C('pollute.s2','figurative','The official feared that bribery would pollute the investigation.','这名官员担心贿赂会玷污调查过程。','pollute the investigation','verb + object','The figurative sense means damage or corrupt something.')],M('The spill polluted the bay by making its water cleaner and safer for fish.','The spill polluted the bay by contaminating its water and harming fish.','Pollute means contaminate; a spill does not clean the water.','meaning'),[Q(1,'What did the oil pollute?','coastal water','a poem’s rhythm','a committee vote','Pollute can make water dirty with harmful substances.'),Q(2,'What might bribery pollute figuratively?','an investigation','a river only','a seed pod','The figurative sense means corrupt or damage.'),Q(1,'What harm followed the spill?','fish died','the water became pure','the tanker grew flowers','The context says pollution killed fish.'),Q(2,'Which sentence uses pollute figuratively?','Lies polluted the public debate.','The factory polluted the river.','The factory repaired the drain.','The first sentence means lies damaged the debate.')]);
P('polluter','From pollute + -er, a person or thing that causes pollution.',C('polluter.s1','environment','The factory was fined as a major polluter after inspectors found untreated waste entering the stream.','检查人员发现未经处理的废物流入溪流后，这家工厂因主要污染者身份被罚款。','major polluter','noun complement','A polluter is an entity that releases pollution.'),M('The factory was called a polluter because it filtered every harmful substance before discharge.','The factory was called a polluter because it released untreated waste into the stream.','A polluter causes contamination; filtering waste prevents it.','meaning'),[Q(1,'Why was the factory fined?','untreated waste entered the stream','it planted trees','it filtered every discharge','The factory was identified as releasing pollution.'),Q(1,'What is a polluter?','a source of pollution','a person who cleans every spill','a type of flower','A polluter is someone or something that causes pollution.'),Q(1,'Which could be a polluter?','a plant releasing toxic emissions','a clean rain barrel','a recycling bin used correctly','A polluter releases contaminants.'),Q(1,'What does -er indicate in polluter?','an agent or source','a past event','a plural form','The suffix marks the source that pollutes.')]);


})();
